    p_map = {2: 'second', 3: 'third', 4: 'fourth'}
    while True:
        p = rng.choice([2, 3, 4])
        a = rng.randint(1, 8)
        c = rng.randint(1, 8)

        for _ in range(100):
            b = rng.randint(a + 1, a + 15)

            d_upper_bound = (b * c - 1) // a
            d_lower_bound = c + 1

            if d_lower_bound > d_upper_bound:
                continue

            d = rng.randint(d_lower_bound, d_upper_bound)

            if a * d >= b * c:
                continue

            A = a * (d - c)
            B = c * (b - a)

            if B <= A:
                continue

            if B > (3**p) * A:
                continue

            try:
                m_max_float = (A**(1/p) + B**(1/p)) / (B**(1/p) - A**(1/p))
                if m_max_float < 2:
                    continue
            except (ValueError, ZeroDivisionError):
                continue

            return {
                'p': p,
                'p_ord': p_map[p],
                'a': a,
                'b': b,
                'c': c,
                'd': d
            }

