def verifier(assign):
    a, b, c, d, p = assign['a'], assign['b'], assign['c'], assign['d'], assign['p']

    if not all(isinstance(i, int) for i in [a, b, c, d, p]): return False, None
    if not all(i > 0 for i in [a, b, c, d, p]): return False, None
    if not (a < b and c < d): return False, None
    if not (a * d < b * c): return False, None

    A = a * (d - c)
    B = c * (b - a)

    if B <= A:
        return False, None

    low, high = 1, 200000
    m_max = 0
    while low <= high:
        m = (low + high) // 2
        if m == 0: low = 1; continue
        try:
            lhs = A * (m + 1)**p
            rhs = B * (m - 1)**p
        except OverflowError:
            lhs = float('inf')
            rhs = 0

        if rhs < 0 or lhs >= rhs:
            m_max = m
            low = m + 1
        else:
            high = m - 1

    if m_max < 1:
        return False, None

    answer = (a * (m_max + 1)**p) // (b - a)
    if answer <= 0:
        return False, None

    def count_powers(n):
        if n <= 0: return 0
        L_num, L_den = n * (d - c), c
        R_num, R_den = n * (b - a), a

        search_upper_bound = int((R_num/R_den)**(1/p)) + 5 if R_num > 0 else 5

        low, high = 0, search_upper_bound
        m_min = high + 1
        while low <= high:
            m = (low + high) // 2
            if m == 0: low = 1; continue
            try: val = m**p
            except OverflowError: val = float('inf')

            if val == float('inf') or val * L_den > L_num:
                m_min = m
                high = m - 1
            else:
                low = m + 1

        low, high = 0, search_upper_bound
        m_max_k = -1
        while low <= high:
            m = (low + high) // 2
            if m == 0: low = 1; continue
            try: val = m**p
            except OverflowError: val = float('inf')

            if val != float('inf') and val * R_den < R_num:
                m_max_k = m
                low = m + 1
            else:
                high = m - 1

        if m_max_k < m_min:
            return 0
        return m_max_k - m_min + 1

    if count_powers(answer) != 1:
        return False, None
    if count_powers(answer + 1) <= 1:
        return False, None

    return True, answer


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

